import math


def make_patch_grid(h, w, d_v):
    grid = []
    val = 0.0
    for r in range(h):
        row = []
        for c in range(w):
            vec = []
            for ch in range(d_v):
                vec.append(val)
                val += 1.0
            row.append(vec)
        grid.append(row)
    return grid


def pad_even_grid(grid):
    h = len(grid)
    w = len(grid[0])
    d_v = len(grid[0][0])
    padded = []
    for r in range(h):
        new_row = []
        for c in range(w):
            new_row.append(list(grid[r][c]))
        if w % 2 == 1:
            zeros = []
            for ch in range(d_v):
                zeros.append(0.0)
            new_row.append(zeros)
        padded.append(new_row)
    if h % 2 == 1:
        extra_row = []
        for c in range(len(padded[0])):
            zeros = []
            for ch in range(d_v):
                zeros.append(0.0)
            extra_row.append(zeros)
        padded.append(extra_row)
    return padded


def pixel_shuffle_2x2(grid):
    h = len(grid)
    w = len(grid[0])
    if h % 2 != 0 or w % 2 != 0:
        grid = pad_even_grid(grid)
        h = len(grid)
        w = len(grid[0])
    tokens = []
    for r in range(0, h, 2):
        for c in range(0, w, 2):
            merged = []
            for dr in (0, 1):
                for dc in (0, 1):
                    for val in grid[r + dr][c + dc]:
                        merged.append(val)
            tokens.append(merged)
    return tokens


def sum_squares_grid(grid):
    total = 0.0
    for row in grid:
        for vec in row:
            for val in vec:
                total += val * val
    return total


def sum_squares_tokens(tokens):
    total = 0.0
    for vec in tokens:
        for val in vec:
            total += val * val
    return total


# ১) 4x4 Patch Grid (d_v = 3) -> 16 raw tokens -> 4 compressed tokens of dim 12
grid_4x4 = make_patch_grid(4, 4, 3)
tokens_ps = pixel_shuffle_2x2(grid_4x4)
energy_before = sum_squares_grid(grid_4x4)
energy_after = sum_squares_tokens(tokens_ps)
assert len(tokens_ps) == 4 and len(tokens_ps[0]) == 12
assert abs(energy_before - energy_after) < 1e-9

# ২) 2-Layer MLP Projection (4*d_v = 12 -> d_llm = 8) with tanh activation
d_in = 12
d_llm = 8
llm_embeds = []
for tok in tokens_ps:
    hidden = []
    for j in range(d_llm):
        acc = 0.0
        for i in range(d_in):
            acc += tok[i] * 0.05
        hidden.append(math.tanh(acc))
    llm_embeds.append(hidden)

# ৩) বিজোড় Grid (যেমন 378x378, P=14 -> 27x27) Padding Guard যাচাই
odd_grid = make_patch_grid(3, 3, 2)
odd_tokens = pixel_shuffle_2x2(odd_grid)

print(f"4x4 Grid: RawTokens=16 -> PixelShuffleTokens={len(tokens_ps)} (dim={len(tokens_ps[0])})")
print(f"L2 Energy: Before={energy_before:.1f} == After={energy_after:.1f} (Zero Loss!)")
print(f"First Super-Token (top-left 2x2): {tokens_ps[0]}")
print(f"Projected LLM Embed Shape: ({len(llm_embeds)}, {len(llm_embeds[0])})")
print(f"Odd 3x3 Grid -> Auto-Padded 4x4 -> CompressedTokens={len(odd_tokens)} (dim={len(odd_tokens[0])})")
